<?php
require __DIR__.'/config.php';$me=require_auth();$uid=(int)$me['id'];$pdo=db();try{sync_approval_messages($pdo,(int)$me['customer_id'],$uid);}catch(Throwable $x){}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=(string)($_POST['action']??'');if($action==='all'){$s=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=? AND is_read=0');$s->execute([$uid]);flash('All notifications marked as read.');go('notifications.php');}elseif($action==='read'){$id=filter_var($_POST['notification_id']??null,FILTER_VALIDATE_INT);if($id){$s=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE notification_id=? AND user_id=?');$s->execute([(int)$id,$uid]);}flash('Notification marked as read.');go('notifications.php');}else{http_response_code(400);exit('Invalid notification action.');}}
$s=$pdo->prepare('SELECT notification_id,type,message,is_read,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC,notification_id DESC LIMIT 100');$s->execute([$uid]);$rows=$s->fetchAll();render_start('Notifications');?>
<section class="page-heading"><div class="eyebrow dark">Updates from BankEase</div><h1>Notifications</h1><p>Review approvals, account updates, and money movement messages.</p></section><?php if($rows):?><div class="notification-toolbar"><span class="muted"><?=unread_notification_count($uid)?> unread</span><form method="post"><?=csrf()?><button class="button pale" type="submit" name="action" value="all">Mark all as read</button></form></div><div class="notification-list"><?php foreach($rows as $n):?><article class="notification-item <?=$n['is_read']?'read':'unread'?>"><div class="notification-icon" aria-hidden="true"><?=str_contains($n['type'],'transfer')?'↔':(str_contains($n['type'],'loan')?'◈':(str_contains($n['type'],'account')?'▣':'•'))?></div><div class="notification-copy"><div class="notification-meta"><strong><?=e(ucwords(str_replace('_',' ',$n['type'])))?></strong><time datetime="<?=e($n['created_at'])?>"><?=e($n['created_at'])?></time><?php if(!$n['is_read']):?><span class="badge">New</span><?php endif;?></div><p><?=e($n['message'])?></p><?php if(!$n['is_read']):?><form method="post"><?=csrf()?><input type="hidden" name="notification_id" value="<?=$n['notification_id']?>"><button class="text-button" type="submit" name="action" value="read">Mark as read</button></form><?php endif;?></div></article><?php endforeach;?></div><?php else:?><div class="empty">You’re all caught up. New updates will appear here.</div><?php endif;?><?php render_end();?>
